map "http://hl7.org/fhir/StructureMap/253f460e-ef11-4af7-a2cc-80808280072f" = 'eCBIS Household Visit Schedule'

uses "http://hl7.org/fhir/StructureDefinition/Parameters" as source
uses "http://hl7.org/fhir/StructureDefinition/CarePlan" as target

group eCBISHouseholdRoutineVisit(source src : Parameters, target tgt: CarePlan) {
    src -> evaluate(src, $this.parameter.where(name='subject').resource) as subject,
            evaluate(src, $this.parameter.where(name='period').value) as period,
            evaluate(src, $this.parameter.where(name='depends-on').resource.entry.where(resource is QuestionnaireResponse).resource) as questionnaireResponse
            then extractTask(period, questionnaireResponse, subject, tgt) "r_careplan";
}

group extractTask(
    source period: Period, source questionnaireResponse: QuestionnaireResponse,
    source subject : Group, target careplan: CarePlan){

    // fill task into careplan contained and add reference in activity.outcome
    subject -> create('Task') as task then {
        subject -> task.id = uuid(),
               task.identifier = create('Identifier') as iden, iden.value = uuid(), iden.use = 'official',
               task.status = 'requested',
               task.intent = 'plan',
               task.executionPeriod = period,
               task.priority = 'routine',
               task.description = 'Routine visit',
               task.for = create('Reference') as ref, ref.reference = evaluate(subject, $this.id.replaceMatches('/_history/.*', '')),
               task.authoredOn = evaluate(subject, now()),
               task.requester = evaluate(subject, $this.generalPractitioner.first()),
               task.owner = evaluate(subject, $this.generalPractitioner.first()) "r_task_data";

        subject where(careplan.id.exists()) -> task.basedOn = create('Reference') as ref, ref.reference = evaluate(careplan, $this.id.replaceMatches('/_history/.*', '')) "r_task_based_on";
        subject where(careplan.id.exists().not()) -> task.basedOn = reference(careplan) "r_task_based_on";

        // if QR questionnaireID is Family Registration Questionnaire
        subject where(questionnaireResponse.questionnaire.value = 'Questionnaire/f210a832-857f-49e6-93f5-399eec4f4edb') then {
            // modify period.end on the end of current month
            subject then extractPeriodForFirstTask(subject, task) "r_task_period_extr";
        } "r_qr_fr_data";

         // if QR questionnaireID is Household Visit Questionnaire
        subject where(questionnaireResponse.questionnaire.value = 'Questionnaire/5458ecb6-835a-4f11-873f-2abfdfeec93c') then {
            // modify period.start to be on the first date of next month till end of next month
            subject then extractPeriod(subject, task) "r_task_period_extr";
        } "r_qr_hv_data";

        // Add the valueReference
        subject -> task.input = create('Task_Input') as input then {
            subject -> input.value = create('Reference') as valueRef, valueRef.reference = 'PlanDefinition/cd1df165-be89-470f-8124-5b495fd133e9' "r_task_input_value_ref";
            subject -> input.type = create('CodeableConcept') as taskCode then extractTaskPlanDefinitionCode(subject, taskCode) "r_task_input_cod";
        } "r_task_input";

        subject -> task.code = create('CodeableConcept') as codeConcept then extractCode(subject, codeConcept) "rule_code";

        subject -> task.groupIdentifier = create('Identifier') as groupIdentifier then {
            subject -> groupIdentifier.value = "household_routine_visit" "rule_group_identifier_value";
            subject -> groupIdentifier.use = "secondary" "rule_group_identifier_use";
        } "rule_group_identifier";

        // household routine followup form
        subject -> task.reasonReference = create('Reference') as ref, ref.reference = 'Questionnaire/5458ecb6-835a-4f11-873f-2abfdfeec93c' "r_task_reason_ref";

        // create activity.detail of type/kind Task for this Task if not exists
        subject where(careplan.activity.where(detail.kind = 'Task').exists().not())
                -> careplan.activity = create('CarePlan_Activity') as activity then {
                   subject -> activity.detail = create('CarePlan_ActivityDetail') as det then {
                       subject -> det.kind = 'Task' "r_act_det_data";
                   } "r_act_det";
               } "r_cp_acti";

        // add task to careplan only if its valid and not expired
        subject where(task.executionPeriod.start >= today() or task.executionPeriod.end >= today()) then {
                 subject -> evaluate(careplan, activity.where(detail.kind = 'Task')) as activity,
                            activity.outcomeReference = reference(task) "r_cp_task_ref";
                 subject -> careplan.contained = task  "r_add_task";
        } "r_cp_task";
    } "r_task";
}

group extractCode(source subject: Patient, target concept: CodeableConcept) {
    subject -> concept.coding = c("http://snomed.info/sct", "310588009") as taskCoding then {
        subject -> taskCoding.display = 'Routine visit' "rule_task_code_diplay";
    } "rule_task_code";
    subject -> concept.text = 'Routine visit' "rule_code_text";
}

group extractTaskPlanDefinitionCode(source subject: Group, target taskCode: CodeableConcept) {
    subject -> taskCode.coding = c("http://smartregister.org/", "plan_definition") as coding, coding.display = 'Plan Definition Reference' "r_cp_cod_disp";
    subject -> taskCode.text = 'Plan Definition Reference' "r_cp_cc_txt";
}

//only updating the endDate till end of the month, startDate will remain as today()
group extractPeriodForFirstTask(source subject: Patient, target task: Task) {
    subject -> evaluate(task, $this.executionPeriod.start) as start, evaluate(task, $this.executionPeriod.end) as end then {
        subject -> create('Period') as period then {

         subject -> create('date') as startDate,
                    startDate.value = evaluate(start, $this.value), //startDate will remain same
                    create('date') as maxMonth,
                    maxMonth.value = evaluate(end, $this.value.substring(0,7) + '-01'),
                    evaluate(maxMonth, $this - "1 days".toQuantity()) as endDate
                    then extractPeriodTime(startDate, endDate, period) "r_task_period_extr";

            subject -> task.executionPeriod = period "r_task_per";

        } "rule_period";
    } "r_per";
}

group extractPeriod(source subject: Group, target task: Task) {
    subject -> evaluate(task, $this.executionPeriod.start) as start, evaluate(task, $this.executionPeriod.end) as end then {
        subject -> create('Period') as period then {

         subject -> create('date') as startDate,
                    startDate.value = evaluate(start, $this.value.substring(0,7) + '-01'),
                    create('date') as maxMonth,
                    maxMonth.value = evaluate(end, $this.value.substring(0,7) + '-01'),
                    evaluate(maxMonth, $this - "1 days".toQuantity()) as endDate
                    then extractPeriodTime(startDate, endDate, period) "r_task_period_extr";

            subject -> task.executionPeriod = period "r_task_per";

        } "rule_period";
    } "r_per";
}

group extractPeriodTime(source start: DateType, source end: DateType, target period: Period) {
    start -> period.start = create('dateTime') as dt,
             dt.value = evaluate(start, $this.value.substring(0,10) + 'T00:00:00.00Z') "r_per_start";

    end -> period.end = create('dateTime') as dt,
           dt.value = evaluate(end, $this.value.substring(0,10) + 'T00:00:00.00Z') "r_per_end";
}